integrity=[]
for item in data['matching_artifact_names']:
    p=Path(item['path']);before=p.stat()
    record={'path':str(p),'sha256':sha(p),'bytes':before.st_size,'sqlite_opened':False,'content_copied':False}
    if p.suffix=='.json':
        try:
            parsed=read(p);record['top_level_field_names']=list(parsed) if isinstance(parsed,dict) else []
            record['values_recorded']=False
        except (ValueError,OSError):record['json_parse']='NOT_VERIFIED'
    side=p.with_name(p.name+'.sha256');record['checksum_sidecar_exists']=side.is_file()
    record['before_after_metadata_equal']=before.st_size==p.stat().st_size and before.st_mtime_ns==p.stat().st_mtime_ns
    record['consistent_restorable_snapshot']='NOT_ESTABLISHED: hash only; no SQLite/schema/WAL recovery or integrity check run'
    integrity.append(record)
write('DATA_BACKUP_INTEGRITY.json',{'timestamp':now(),'backup_and_manifest_hashes':integrity,'scope':'Existing named offline backup DB bytes hashed without SQLite open; no active DB hash/open, no data values recorded. Manifest field names only. No consistency/restore claim.'})
